/**
 * * `invoice` - Invoice
 * * `credit_note` - Credit note
 * * `debit_note` - Debit note
 */
export const zVoucherKind = z.enum([
    'invoice',
    'credit_note',
    'debit_note'
]);

/**
 * * `1` - Factura A
 * * `2` - Nota de Débito A
 * * `3` - Nota de Crédito A
 * * `6` - Factura B
 * * `7` - Nota de Débito B
 * * `8` - Nota de Crédito B
 * * `11` - Factura C
 * * `12` - Nota de Débito C
 * * `13` - Nota de Crédito C
 */
export const zVoucherType = z.union([
    z.literal(1),
    z.literal(2),
    z.literal(3),
    z.literal(6),
    z.literal(7),
    z.literal(8),
    z.literal(11),
    z.literal(12),
    z.literal(13)
]);

